function EmailField({ error }) {
  const id = useId()
  return <>
    <label htmlFor={id}>Email</label>
    <input id={id} type="email" aria-invalid={Boolean(error)} aria-describedby={error ? id + "-error" : undefined} />
    {error && <p id={id + "-error"}>{error}</p>}
  </>
}

function NameForm() {
  const [message, formAction, pending] = useActionState(
    async (_previous, data) => String(data.get("name") ?? "").trim() ? "Имя принято" : "Введите имя",
    ""
  )
  return <form action={formAction}>
    <input name="name" /><button disabled={pending}>Проверить</button><p aria-live="polite">{message}</p>
  </form>
}

import { useFormStatus } from "react-dom"

function SubmitButton() {
  const { pending } = useFormStatus()
  return <button type="submit" disabled={pending}>{pending ? "Отправка..." : "Отправить"}</button>
}
